(function(){'use strict';if('scrollRestoration' in history){history.scrollRestoration='manual';}document.addEventListener('DOMContentLoaded',()=>{const path=window.location.pathname;const isSubpage=path.includes('/about-us')|| path.includes('/solutions/')|| path.includes('/barcode-label-')|| path.includes('/contacts')|| path.includes('/careers');if(!isSubpage){window.scrollTo({top:0,left:0});}init();});function init(){loadAndHydrate().then(()=>{initCounterAnimation();handleSubpageScroll();});setupOfflineNavigation();initThemeSwitcher();initStickyHeader();initMobileMenu();initDesktopMenuAccessibility();initScrollReveal();initLiveDashboardMetric();initParallaxHero();init3DTilt();initSpotlightHover();initMagneticButtons();initBackToTop();initSmoothScroll();initContactForm();}function getRelativePrefix(){const script=document.querySelector('script[src*="main.min.js"],script[src*="main.js"]');if(script){const src=script.getAttribute('src');if(src){const idx=src.indexOf('js/main');if(idx !==-1){return src.substring(0,idx);}}}return './';}function resolveAssetPath(url){if(!url || url.startsWith('http')|| url.startsWith('data:'))return url;if(url.startsWith('/'))url=url.substring(1);if(url.startsWith('./'))url=url.substring(2);return getRelativePrefix()+url;}function resolveAnchorPath(href){if(!href || href.startsWith('http')|| !href.startsWith('#'))return href;if(href==='#main-content' || href==='#footer')return href;const prefix=getRelativePrefix();if(prefix==='./')return href;const isFileProtocol=window.location.protocol==='file:';if(isFileProtocol){return prefix+'index.html'+href;}else{return prefix+href;}}function setupOfflineNavigation(){if(window.location.protocol !=='file:')return;document.addEventListener('click',function(e){const link=e.target.closest('a');if(!link)return;const href=link.getAttribute('href');if(!href || href.startsWith('http')|| href.startsWith('mailto:')|| href.startsWith('tel:')|| href.startsWith('#'))return;if(href.endsWith('/')){e.preventDefault();window.location.href=href+'index.html';}});}async function loadAndHydrate(){try{const response=await fetch(resolveAssetPath('content.json')+'?v='+Date.now());if(!response.ok)throw new Error('Failed to load content.json');const data=await response.json();hydrateSite(data);}catch(error){console.warn('Content hydration failed,using fallback HTML markup:',error);}}function hydrateSite(data){if(data.site){const headerLogoImg=document.querySelector('.header .logo__mark img');if(headerLogoImg && data.site.logoHeader){headerLogoImg.setAttribute('src',resolveAssetPath(data.site.logoHeader));headerLogoImg.setAttribute('alt',(data.site.name || 'Astrix Glow')+' Logo');}else if(headerLogoImg && data.site.logo){headerLogoImg.setAttribute('src',resolveAssetPath(data.site.logo));headerLogoImg.setAttribute('alt',(data.site.name || 'Astrix Glow')+' Logo');}const footerLogoImg=document.querySelector('.footer .logo__mark img');if(footerLogoImg && data.site.logoFooter){footerLogoImg.setAttribute('src',resolveAssetPath(data.site.logoFooter));footerLogoImg.setAttribute('alt',(data.site.name || 'Astrix Glow')+' Logo');}else if(footerLogoImg && data.site.logo){footerLogoImg.setAttribute('src',resolveAssetPath(data.site.logo));footerLogoImg.setAttribute('alt',(data.site.name || 'Astrix Glow')+' Logo');}const logoTexts=document.querySelectorAll('.logo__text');logoTexts.forEach(el=>{if(data.site.name==='Astrixglow'){el.innerHTML='Astrix<em>Glow</em>';}else if(data.site.name){el.textContent=data.site.name;}});const logoLinks=document.querySelectorAll('.logo');logoLinks.forEach(link=>{link.setAttribute('aria-label',(data.site.name || 'Astrix Glow')+'-Home');});}function setText(id,text){const el=document.getElementById(id);if(el && text !==undefined)el.textContent=text;}function escapeHtml(str){if(!str)return '';return str .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');}if(data.site && data.site.whatsapp && data.site.whatsappMessage){const waUrl='https://wa.me/'+data.site.whatsapp+'?text='+encodeURIComponent(data.site.whatsappMessage);const waLinks=document.querySelectorAll('a[href*="wa.me"],#whatsapp-link,.wa-link');waLinks.forEach(link=>{link.setAttribute('href',waUrl);});}if(data.hero){const heroEyebrow=document.getElementById('hero-eyebrow');if(heroEyebrow && data.hero.eyebrowText){const dot=heroEyebrow.querySelector('.hero__eyebrow-dot');heroEyebrow.innerHTML='';if(dot)heroEyebrow.appendChild(dot);heroEyebrow.appendChild(document.createTextNode(' '+data.hero.eyebrowText));}const heroTitle=document.getElementById('hero-title');if(heroTitle && data.hero.headline && data.hero.subheadline){heroTitle.innerHTML=escapeHtml(data.hero.headline)+'<span class="hero__title-line2">'+escapeHtml(data.hero.subheadline)+'</span>';}setText('hero-desc',data.hero.description);const heroPrimary=document.getElementById('hero-cta-primary');if(heroPrimary && data.hero.ctaPrimary){heroPrimary.textContent=data.hero.ctaPrimary.label;heroPrimary.setAttribute('href',resolveAnchorPath(data.hero.ctaPrimary.href));}const heroSecondary=document.getElementById('hero-cta-secondary');if(heroSecondary && data.hero.ctaSecondary){heroSecondary.textContent=data.hero.ctaSecondary.label;heroSecondary.setAttribute('href',resolveAnchorPath(data.hero.ctaSecondary.href));}const heroImg=document.querySelector('.tilt-card img');if(heroImg && data.hero.image){heroImg.setAttribute('src',resolveAssetPath(data.hero.image));if(data.hero.imageAlt)heroImg.setAttribute('alt',data.hero.imageAlt);}}if(data.about){setText('about-tag',data.about.subtitle);setText('about-title',data.about.title);setText('about-desc',data.about.description);setText('about-badge-num',data.about.badgeValue);setText('about-badge-label',data.about.badgeLabel);const aboutImg=document.getElementById('about-img');if(aboutImg && data.about.image){aboutImg.setAttribute('src',resolveAssetPath(data.about.image));if(data.about.imageAlt)aboutImg.setAttribute('alt',data.about.imageAlt);}if(data.about.features){const featCards=document.querySelectorAll('.about__feat');featCards.forEach((card,index)=>{const featData=data.about.features[index];if(featData){const titleEl=card.querySelector('.about__feat-title');const textEl=card.querySelector('.about__feat-text');if(titleEl)titleEl.textContent=featData.title;if(textEl)textEl.textContent=featData.text;}});}}if(data.products){setText('products-tag',data.products.subtitle);setText('products-title',data.products.title);setText('products-desc',data.products.description);}if(data.solutions){setText('solutions-tag',data.solutions.subtitle);setText('solutions-title',data.solutions.title);setText('solutions-desc',data.solutions.description);if(data.solutions.items){const solCards=document.querySelectorAll('.solutions__grid .sol');solCards.forEach((card,index)=>{const solData=data.solutions.items[index];if(solData){const titleEl=card.querySelector('.sol__title');const descEl=card.querySelector('.sol__desc');const imgEl=card.querySelector('.sol__img img');if(titleEl)titleEl.textContent=solData.title;if(descEl)descEl.textContent=solData.description;if(imgEl && solData.image){imgEl.setAttribute('src',resolveAssetPath(solData.image));imgEl.setAttribute('alt',solData.title);}if(solData.highlights){const chipEls=card.querySelectorAll('.sol__chip');chipEls.forEach((chip,cIndex)=>{const chipText=solData.highlights[cIndex];if(chipText){const svg=chip.querySelector('svg');chip.innerHTML='';if(svg)chip.appendChild(svg);chip.appendChild(document.createTextNode(chipText));}});}}});}}if(data.caseStudies){const caseCards=document.querySelectorAll('.cases__grid .case-card');caseCards.forEach((card,index)=>{const caseData=data.caseStudies[index];if(caseData){const metricEl=card.querySelector('.case-card__metric');const metricLabelEl=card.querySelector('.case-card__metric-label');const clientEl=card.querySelector('.case-card__client');const titleEl=card.querySelector('.case-card__title');const descEl=card.querySelector('.case-card__desc');if(metricEl && caseData.metric){const numVal=parseFloat(caseData.metric.replace(/[^\d.-]/g,''));const suffix=caseData.metric.replace(/[\d.-]/g,'');metricEl.setAttribute('data-count',numVal);metricEl.setAttribute('data-suffix',suffix);metricEl.textContent='0';}if(metricLabelEl)metricLabelEl.textContent=caseData.metricLabel;if(clientEl)clientEl.textContent=caseData.client;if(titleEl)titleEl.textContent=caseData.title;if(descEl)descEl.textContent=caseData.description;if(caseData.tags){const tagEls=card.querySelectorAll('.case-card__tag');tagEls.forEach((tagEl,tIndex)=>{if(caseData.tags[tIndex]){tagEl.textContent=caseData.tags[tIndex];}});}}});}if(data.services){setText('services-tag',data.services.subtitle);setText('services-title',data.services.title);setText('services-desc',data.services.description);if(data.services.items){const svcCards=document.querySelectorAll('.services__grid .svc');svcCards.forEach((card,index)=>{const svcData=data.services.items[index];if(svcData){const titleEl=card.querySelector('.svc__title');const descEl=card.querySelector('.svc__desc');if(titleEl)titleEl.textContent=svcData.title;if(descEl)descEl.textContent=svcData.description;}});}}if(data.testimonials){setText('testimonials-tag',data.testimonials.subtitle);setText('testimonials-title',data.testimonials.title);setText('testimonials-desc',data.testimonials.description);const testiCards=document.querySelectorAll('.testimonials__grid .testi');testiCards.forEach((card,index)=>{const testiData=data.testimonials[index];if(testiData){const textEl=card.querySelector('.testi__text');const nameEl=card.querySelector('.testi__name');const roleEl=card.querySelector('.testi__role');if(textEl)textEl.textContent='"'+testiData.quote+'"';if(nameEl)nameEl.textContent=testiData.author;if(roleEl)roleEl.textContent=testiData.role+','+testiData.company;}});}if(data.cta){setText('cta-title',data.cta.headline);setText('cta-desc',data.cta.description);const ctaBtn=document.getElementById('cta-btn');if(ctaBtn){ctaBtn.textContent=data.cta.buttonLabel;ctaBtn.setAttribute('href',resolveAnchorPath(data.cta.buttonHref));}}if(data.contact){setText('contact-tag',data.contact.subtitle);setText('contact-title',data.contact.title);setText('contact-desc',data.contact.description);}if(data.footer && data.site){setText('contact-hq-addr',data.footer.globalHQ.address);setText('contact-in-addr',data.footer.corporateOffice.address);const phonesContainer=document.getElementById('contact-phones');if(phonesContainer && data.footer.phoneUSA && data.footer.phoneIndia){let phonesHtml='';if(data.footer.phoneUSA[0]){const num=data.footer.phoneUSA[0].number;phonesHtml+='USA:<a href="tel:'+num.replace(/[^\d+]/g,'')+'">'+num+'</a><br>';}if(data.footer.phoneIndia[0]){const num=data.footer.phoneIndia[0];phonesHtml+='India:<a href="tel:'+num.replace(/[^\d+]/g,'')+'">'+num+'</a>';}phonesContainer.innerHTML=phonesHtml;}const emailsContainer=document.getElementById('contact-emails');if(emailsContainer && data.site.email && data.site.emailSecondary){emailsContainer.innerHTML='<a href="mailto:'+data.site.email+'">'+data.site.email+'</a>/<a href="mailto:'+data.site.emailSecondary+'">'+data.site.emailSecondary+'</a>';}}if(data.footer){setText('footer-desc',data.footer.description);setText('footer-copyright',data.footer.copyright);const brochureBtn=document.getElementById('footer-brochure');if(brochureBtn && data.brochure){const svg=brochureBtn.querySelector('svg');brochureBtn.innerHTML='';if(svg)brochureBtn.appendChild(svg);brochureBtn.appendChild(document.createTextNode(' '+data.brochure.label));brochureBtn.setAttribute('href',resolveAssetPath(data.brochure.url));}}if(data.milestones){const timeline=document.getElementById('footer-timeline');if(timeline){timeline.innerHTML=data.milestones.map(m=>`<div class="footer__timeline-item"><span class="footer__timeline-year">${escapeHtml(m.year)}</span><span class="footer__timeline-text">${escapeHtml(m.event)}</span></div>`).join('');}}if(data.certifications){const certs=document.getElementById('footer-certs');if(certs){certs.innerHTML=data.certifications.map(c=>`<span class="footer__cert-badge">${escapeHtml(c)}</span>`).join('');}}}function handleSubpageScroll(){const path=window.location.pathname;let targetId='';if(path.includes('/about-us')){targetId='#about';}else if(path.includes('/solutions/barcode-retail-labels')){targetId='#solutions';}else if(path.includes('/solutions/asset-label-tracking-system')){targetId='#solutions';}else if(path.includes('/solutions/warehouse-label-logistics-management-system')){targetId='#solutions';}else if(path.includes('/barcode-label-application-engineering')|| path.includes('/barcode-label-product-testing')|| path.includes('/barcode-label-implementation-consulting')){targetId='#services';}else if(path.includes('/contacts')){targetId='#contact';}else if(path.includes('/careers')){targetId='#contact';}if(targetId){requestAnimationFrame(()=>{setTimeout(()=>{const targetEl=document.querySelector(targetId);if(targetEl){const header=document.getElementById('header');const headerHeight=header ? header.offsetHeight:80;const targetPos=targetEl.getBoundingClientRect().top+window.scrollY-headerHeight-16;window.scrollTo({top:targetPos,behavior:'auto'});}},50);});}}function initThemeSwitcher(){const toggle=document.getElementById('theme-toggle');if(!toggle)return;const savedTheme=localStorage.getItem('theme')|| 'dark';document.documentElement.setAttribute('data-theme',savedTheme);updateToggleAriaLabel(toggle,savedTheme);toggle.addEventListener('click',function(){const currentTheme=document.documentElement.getAttribute('data-theme');const newTheme=currentTheme==='light' ? 'dark':'light';document.documentElement.setAttribute('data-theme',newTheme);localStorage.setItem('theme',newTheme);updateToggleAriaLabel(toggle,newTheme);});}function updateToggleAriaLabel(button,activeTheme){const targetLabel=activeTheme==='dark' ? 'Switch to Light Theme':'Switch to Dark Theme';button.setAttribute('aria-label',targetLabel);}function initStickyHeader(){const header=document.getElementById('header');if(!header)return;const threshold=50;function onScroll(){if(window.scrollY>threshold){header.classList.add('is-scrolled');}else{header.classList.remove('is-scrolled');}}window.addEventListener('scroll',onScroll,{passive:true});onScroll();}function initMobileMenu(){const toggle=document.getElementById('mobile-toggle');const panel=document.getElementById('nav-mobile-panel');if(!toggle || !panel)return;toggle.addEventListener('click',function(){const isOpen=panel.classList.contains('is-open');panel.classList.toggle('is-open');toggle.classList.toggle('is-active');toggle.setAttribute('aria-expanded',!isOpen);document.body.style.overflow=isOpen ? '':'hidden';});const submenuTriggers=panel.querySelectorAll('[data-submenu]');submenuTriggers.forEach(function(trigger){trigger.addEventListener('click',function(){const submenuId=this.getAttribute('data-submenu');const submenu=document.getElementById(submenuId);if(!submenu)return;const isExpanded=submenu.classList.contains('is-open');submenu.classList.toggle('is-open');this.classList.toggle('expanded');this.setAttribute('aria-expanded',!isExpanded);});});const mobileLinks=panel.querySelectorAll('a[href^="#"]');mobileLinks.forEach(function(link){link.addEventListener('click',function(){panel.classList.remove('is-open');toggle.classList.remove('is-active');toggle.setAttribute('aria-expanded','false');document.body.style.overflow='';});});document.addEventListener('keydown',function(e){if(e.key==='Escape' && panel.classList.contains('is-open')){panel.classList.remove('is-open');toggle.classList.remove('is-active');toggle.setAttribute('aria-expanded','false');document.body.style.overflow='';toggle.focus();}});}function initDesktopMenuAccessibility(){const navItems=document.querySelectorAll('.nav__item');navItems.forEach(item=>{const link=item.querySelector('.nav__link[aria-haspopup="true"]');if(!link)return;item.addEventListener('focusin',()=>{link.setAttribute('aria-expanded','true');});item.addEventListener('focusout',()=>{link.setAttribute('aria-expanded','false');});item.addEventListener('mouseenter',()=>{link.setAttribute('aria-expanded','true');});item.addEventListener('mouseleave',()=>{link.setAttribute('aria-expanded','false');});});}function initScrollReveal(){if(window.matchMedia('(prefers-reduced-motion:reduce)').matches)return;const revealElements=document.querySelectorAll('.rv,.rv-l,.rv-r,.rv-s,.stg');if(!revealElements.length)return;const observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('is-vis');observer.unobserve(entry.target);}});},{threshold:0.1});revealElements.forEach(function(el){observer.observe(el);});}function initLiveDashboardMetric(){const metricEl=document.getElementById('dashboard-metric');if(!metricEl)return;let baseVal=4812903;function formatNumber(num){return num.toString().replace(/\B(?=(\d{3})+(?!\d))/g,",");}setInterval(function(){const delta=Math.floor(Math.random()*24)+1;baseVal+=delta;metricEl.textContent=formatNumber(baseVal);metricEl.style.color='#38bdf8';setTimeout(function(){metricEl.style.color='';},500);},3500);}function initCounterAnimation(){const counters=document.querySelectorAll('[data-count]');if(!counters.length)return;const observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){animateCounter(entry.target);observer.unobserve(entry.target);}});},{threshold:0.3});counters.forEach(function(counter){observer.observe(counter);});}function animateCounter(el){const target=parseFloat(el.getAttribute('data-count'));const suffix=el.getAttribute('data-suffix')|| '';const isDecimal=target % 1 !==0;const duration=2200;const startTime=performance.now();function easeOutExpo(t){return t===1 ? 1:1-Math.pow(2,-10*t);}function update(currentTime){const elapsed=currentTime-startTime;const progress=Math.min(elapsed/duration,1);const eased=easeOutExpo(progress);let current=eased*target;if(isDecimal){el.textContent=current.toFixed(1)+suffix;}else{el.textContent=Math.round(current)+suffix;}if(progress<1){requestAnimationFrame(update);}}requestAnimationFrame(update);}function initParallaxHero(){if(window.matchMedia('(prefers-reduced-motion:reduce)').matches)return;if(window.innerWidth<1024)return;const hero=document.getElementById('hero');const heroWrapper=document.getElementById('hero-parallax');if(!hero || !heroWrapper)return;hero.addEventListener('mousemove',function(e){const rect=hero.getBoundingClientRect();const x=(e.clientX-rect.left)/rect.width-0.5;const y=(e.clientY-rect.top)/rect.height-0.5;requestAnimationFrame(function(){heroWrapper.style.transform='perspective(1000px)rotateY('+(x*6)+'deg)rotateX('+(-y*6)+'deg)';});});hero.addEventListener('mouseleave',function(){heroWrapper.style.transition='transform 0.6s ease';heroWrapper.style.transform='perspective(1000px)rotateY(0deg)rotateX(0deg)';setTimeout(function(){heroWrapper.style.transition='';},600);});}function init3DTilt(){if(window.matchMedia('(prefers-reduced-motion:reduce)').matches)return;if(window.innerWidth<768)return;const tiltCards=document.querySelectorAll('.tilt-card:not(#hero-parallax)');tiltCards.forEach(function(card){card.addEventListener('mousemove',function(e){const rect=card.getBoundingClientRect();const x=e.clientX-rect.left;const y=e.clientY-rect.top;const xc=rect.width/2;const yc=rect.height/2;const rotateX=-(y-yc)/(rect.height/20);const rotateY=(x-xc)/(rect.width/20);requestAnimationFrame(function(){card.style.setProperty('--rotate-x',rotateX+'deg');card.style.setProperty('--rotate-y',rotateY+'deg');});});card.addEventListener('mouseleave',function(){requestAnimationFrame(function(){card.style.setProperty('--rotate-x','0deg');card.style.setProperty('--rotate-y','0deg');});});});}function initSpotlightHover(){const cards=document.querySelectorAll('.glow-card');cards.forEach(function(card){card.addEventListener('mousemove',function(e){const rect=card.getBoundingClientRect();const x=e.clientX-rect.left;const y=e.clientY-rect.top;requestAnimationFrame(function(){card.style.setProperty('--mouse-x',x+'px');card.style.setProperty('--mouse-y',y+'px');});});});}function initMagneticButtons(){if(window.matchMedia('(prefers-reduced-motion:reduce)').matches)return;if(window.innerWidth<768)return;const magneticBtns=document.querySelectorAll('.btn-magnetic');magneticBtns.forEach(function(btn){btn.addEventListener('mousemove',function(e){const rect=btn.getBoundingClientRect();const x=e.clientX-rect.left-rect.width/2;const y=e.clientY-rect.top-rect.height/2;requestAnimationFrame(function(){btn.style.transform='translate('+(x*0.25)+'px,'+(y*0.25)+'px)';});});btn.addEventListener('mouseleave',function(){requestAnimationFrame(function(){btn.style.transform='translate(0px,0px)';btn.style.transition='transform 0.5s cubic-bezier(0.25,1,0.5,1)';});});btn.addEventListener('mouseenter',function(){btn.style.transition='none';});});}function initBackToTop(){const btn=document.getElementById('back-to-top');if(!btn)return;function checkVisibility(){if(window.scrollY>400){btn.classList.add('is-visible');}else{btn.classList.remove('is-visible');}}window.addEventListener('scroll',checkVisibility,{passive:true});checkVisibility();btn.addEventListener('click',function(){window.scrollTo({top:0,behavior:'smooth'});});}function initSmoothScroll(){const links=document.querySelectorAll('a[href^="#"]');links.forEach(function(link){link.addEventListener('click',function(e){const targetId=this.getAttribute('href');if(targetId==='#')return;const targetEl=document.querySelector(targetId);if(!targetEl)return;e.preventDefault();const headerHeight=document.getElementById('header').offsetHeight;const targetPos=targetEl.getBoundingClientRect().top+window.scrollY-headerHeight-16;window.scrollTo({top:targetPos,behavior:'smooth'});if(history.pushState){history.pushState(null,null,targetId);}});});}function initContactForm(){const form=document.getElementById('contact-form');if(!form)return;form.addEventListener('submit',function(e){e.preventDefault();const name=document.getElementById('contact-name');const email=document.getElementById('contact-email');const message=document.getElementById('contact-message');const submitBtn=document.getElementById('contact-submit-btn');let isValid=true;[name,email,message].forEach(function(field){field.style.borderColor='';field.style.boxShadow='';});if(!name.value.trim()){name.style.borderColor='#EF4444';name.style.boxShadow='0 0 0 3px rgba(239,68,68,0.15)';isValid=false;}if(!email.value.trim()|| !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value)){email.style.borderColor='#EF4444';email.style.boxShadow='0 0 0 3px rgba(239,68,68,0.15)';isValid=false;}if(!message.value.trim()){message.style.borderColor='#EF4444';message.style.boxShadow='0 0 0 3px rgba(239,68,68,0.15)';isValid=false;}if(!isValid)return;const originalText=submitBtn.innerHTML;submitBtn.textContent='Sending secure request...';submitBtn.disabled=true;submitBtn.style.opacity='0.75';setTimeout(function(){submitBtn.textContent='✓ secure Request Sent!';submitBtn.style.background='#22C55E';submitBtn.style.borderColor='#16A34A';submitBtn.style.boxShadow='0 4px 18px rgba(34,197,94,0.35)';setTimeout(function(){form.reset();submitBtn.innerHTML=originalText;submitBtn.disabled=false;submitBtn.style.opacity='';submitBtn.style.background='';submitBtn.style.borderColor='';submitBtn.style.boxShadow='';},3500);},1500);});form.querySelectorAll('.form-input,.form-textarea').forEach(function(input){input.addEventListener('input',function(){this.style.borderColor='';this.style.boxShadow='';});});}})();